import { Accessor, createSignal, mergeProps, ParentComponent, ParentProps, Show } from "solid-js";

import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";

export interface CollapsibleContainerProps {
	titleText: string;
	titleIcon?: string;
	class?: string;
	headerClass?: string;
	centerTitle?: boolean;
	disableFocus?: boolean;
	initiallyCollapsed?: boolean;
	disabled?: boolean;
}

interface CollapsibleHeaderProps extends ActivatableProps {
	titleText: string;
	titleIcon?: string;
	isCollapsed: Accessor<boolean>;
	centerTitle?: boolean;
	headerClass?: string;
}

const CollapsibleHeader: ParentComponent<CollapsibleHeaderProps> = (props: CollapsibleHeaderProps) => {
	return (
		<Activatable
			{...props}
			class={`w-full h-7 flex flex-row items-center relative group ${props.centerTitle ? "justify-center" : ""}`}
			style={{ "background-color": "rgba(38, 39, 46, 0.55)", opacity: props.disabled ? 0.6 : 1 }}
			onActivate={props.onActivate}
			name="Collapsible-Container"
		>
			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
			<div
				class="h-9 w-1\.5 absolute bg-cover bg-center left-0 -top-1"
				style={{ "background-image": "url(blp:base_minitab-endcap)" }}
			/>
			<Show when={props.titleIcon != undefined}>
				<Icon
					class={`${isMobile() ? "size-8" : "size-6"} ml-2 -mr-1 bg-cover bg-center`}
					name={props.titleIcon}
				/>
			</Show>
			<div class={`uppercase text-base text-secondary ml-2 font-title ${props.headerClass}`}>
				<L10n.Compose text={props.titleText} />
			</div>
			<Show when={!props.disabled && !(props.disableFocus && IsControllerActive())}>
				<div
					// not sure why it's complaining only about this "0\.5"
					// eslint-disable-next-line no-useless-escape
					class={`size-6 absolute right-3 top-0\.5 bg-cover bg-center ${!props.isCollapsed() ? "-rotate-90" : ""}`}
					style={{ "background-image": "url(blp:base_component-arrow)" }}
				/>
			</Show>
			<div
				class="h-9 w-1\.5 absolute right-0 -top-1 bg-cover bg-center"
				style={{ "background-image": "url(blp:base_minitab-endcap)" }}
			/>
		</Activatable>
	);
};

function CollapsibleContainerComponent(props: ParentProps<CollapsibleContainerProps>) {
	const [isCollapsed, setIsCollapsed] = createSignal(props.initiallyCollapsed ?? false);

	function toggleCollapsed() {
		setIsCollapsed((value) => !value);
	}
	const mergedProps = mergeProps({ showTitleShadow: true }, props);

	return (
		<div
			class={`flex flex-col ${props.class ?? ""}`}
			classList={{ disabled: props.disabled }}
		>
			<AudioContextProvider
				segment="CollapsibleContainer"
				vars={{ isCollapsed: isCollapsed().toString() }}
			>
				<CollapsibleHeader
					{...{
						isCollapsed: isCollapsed,
						titleText: props.titleText,
						titleIcon: props.titleIcon,
						centerTitle: props.centerTitle,
						useShadow: mergedProps.showTitleShadow,
						headerClass: props.headerClass,
						disableFocus: props.disableFocus,
						disabled: props.disabled,
					}}
					class={`relative ${props.class ?? ""}`}
					onActivate={toggleCollapsed}
				/>
			</AudioContextProvider>
			<Show when={!isCollapsed()}>{props.children}</Show>
		</div>
	);
}

export const CollapsibleContainer = ComponentRegistry.register({
	name: "CollapsibleContainer",
	images: ["blp:base_component-arrow", "blp:base_minitab-endcap"],
	createInstance: CollapsibleContainerComponent,
});
